#include <bits/stdc++.h>
using namespace std;

// Precompute prime factors for all numbers up to MAXN
const int MAXN = 2000000;
vector<int> primeFactors[MAXN + 1];

// DSU for components
struct DSU {
    vector<int> parent;
    DSU(int n) {
        parent.resize(n + 1);
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        return parent[x] == x ? x : parent[x] = find(parent[x]);
    }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a != b) parent[a] = b;
    }
};

// Core solution function
// a: array of positive integers, each <= 2e6
// queries: pairs of 1-based indices into a
// Returns: vector of answers (0, 1, or 2) for each query
vector<int> minimumTransformSteps(int n, const vector<int>& a, const vector<pair<int,int>>& queries) {
    static bool init = false;
    if (!init) {
        init = true;
        vector<bool> isPrime(MAXN + 1, true);
        for (int i = 2; i <= MAXN; ++i) {
            if (isPrime[i]) {
                for (int j = i; j <= MAXN; j += i) {
                    isPrime[j] = false;
                    primeFactors[j].push_back(i);
                }
            }
        }
    }

    DSU dsu(MAXN);
    for (int i = 0; i < n; ++i) {
        int x = a[i];
        for (int p : primeFactors[x]) {
            dsu.unite(x, p);
        }
    }

    // Map to mark pairs of representatives that are connected via a single auxiliary node
    unordered_map<long long, bool> connected;
    for (int i = 0; i < n; ++i) {
        int x = a[i];
        int y = x + 1;
        vector<int> reps;
        reps.push_back(dsu.find(x));
        for (int p : primeFactors[y]) {
            reps.push_back(dsu.find(p));
        }
        // Mark all unordered pairs
        for (size_t u = 0; u < reps.size(); ++u) {
            for (size_t v = u + 1; v < reps.size(); ++v) {
                int uu = reps[u], vv = reps[v];
                if (uu > vv) swap(uu, vv);
                connected[(long long)uu * (MAXN + 1) + vv] = true;
            }
        }
    }

    vector<int> ans;
    ans.reserve(queries.size());
    for (const auto& q : queries) {
        int sIdx = q.first, tIdx = q.second;
        int rs = dsu.find(a[sIdx]);
        int rt = dsu.find(a[tIdx]);
        if (rs == rt) {
            ans.push_back(0);
        } else {
            if (rs > rt) swap(rs, rt);
            bool hasEdge = connected.count((long long)rs * (MAXN + 1) + rt);
            ans.push_back(hasEdge ? 1 : 2);
        }
    }
    return ans;
}

